prompt:
Review this Go settlement-report change for financial correctness. Source report amounts are exact decimal strings before parsing and may use currency-specific scales. Reports can contain captures, refunds, fees, and multiple currencies; one PaymentID can have several lifecycle components. Exact redelivery uses the same report ID and checksum. A corrected report has a new ID, a higher version, and Supersedes pointing to its predecessor; Line.ID identifies the same economic component across corrected versions. Raw reports and posted journals are authoritative audit evidence. Every database call shown commits independently, and the process can crash between any two calls. Report only must-fix findings, each with a reachable failure schedule and the repair invariant; do not implement the change.

type Report struct {
	ID         string
	Checksum   string
	Version    int
	Supersedes string
	Lines      []Line
}

type Line struct {
	ID        string
	PaymentID string
	Currency  string
	Kind      string
	Amount    float64
}

func (s *Service) Ingest(ctx context.Context, report Report) error {
	if report.Supersedes != "" {
		_ = s.reports.Delete(ctx, report.Supersedes)
	}

	for _, line := range report.Lines {
		local, err := s.payments.FindByPaymentID(ctx, line.PaymentID)
		if err != nil {
			continue
		}
		if math.Abs(local.Amount-line.Amount) < 0.01 {
			_ = s.matches.MarkMatched(ctx, line.PaymentID)
			continue
		}

		amount := int64(line.Amount * 100)
		_ = s.ledger.UpdatePostedAmount(ctx, local.JournalID, amount)
		_ = s.adjustments.Insert(ctx, Adjustment{
			ID:       uuid.NewString(),
			LineID:   line.ID,
			Amount:   amount,
			Currency: line.Currency,
		})
	}

	return s.reports.MarkComplete(ctx, report.ID)
}

